ALTER POLICY technical_insert ON public.technical_documents WITH CHECK(company_id=public.current_company_id() AND uploaded_by=auth.uid() AND public.member_is_active(auth.uid()) AND (public.my_role() IN('superuser','supervisor') OR (public.my_role() IN('technician','maintenance') AND status='pending' AND NOT restricted)));
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.guard_ppm_plan()'::regprocedure) INTO definition; definition:=replace(definition,'role IN (''technician'',''supervisor'')','role IN (''technician'',''supervisor'',''maintenance'')'); EXECUTE definition; END $$;
CREATE OR REPLACE FUNCTION public.guard_contact_routing() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; v jsonb; BEGIN
 IF TG_OP='UPDATE' AND (NEW.company_id,NEW.client_id,NEW.id) IS DISTINCT FROM (OLD.company_id,OLD.client_id,OLD.id) THEN RAISE EXCEPTION 'Contact identity cannot change'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.clients WHERE id=NEW.client_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Invalid client company'; END IF;
 IF NEW.site_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.sites WHERE id=NEW.site_id AND client_id=NEW.client_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Contact site must belong to its client'; END IF;
 IF NEW.delivery_preferences IS NULL THEN NEW.all_sites:=(NEW.site_id IS NULL);NEW.site_ids:=CASE WHEN NEW.site_id IS NULL THEN '{}'::uuid[] ELSE ARRAY[NEW.site_id] END;
 ELSIF NEW.delivery_preferences='null'::jsonb THEN NEW.delivery_preferences:=NULL;NEW.all_sites:=(NEW.site_id IS NULL);NEW.site_ids:=CASE WHEN NEW.site_id IS NULL THEN '{}'::uuid[] ELSE ARRAY[NEW.site_id] END;
 ELSE
 IF auth.uid() IS NOT NULL AND NOT public.company_module_access(NEW.company_id,'client_portal') AND (TG_OP='INSERT' OR NEW.delivery_preferences IS DISTINCT FROM OLD.delivery_preferences OR NEW.site_ids IS DISTINCT FROM OLD.site_ids OR NEW.all_sites IS DISTINCT FROM OLD.all_sites) THEN RAISE EXCEPTION 'Client Experience module required for advanced routing'; END IF;
 IF jsonb_typeof(NEW.delivery_preferences)<>'object' OR EXISTS(SELECT 1 FROM unnest(NEW.site_ids)s WHERE NOT EXISTS(SELECT 1 FROM public.sites WHERE id=s AND client_id=NEW.client_id AND company_id=NEW.company_id)) THEN RAISE EXCEPTION 'Invalid routing sites'; END IF;
 FOR k,v IN SELECT * FROM jsonb_each(NEW.delivery_preferences) LOOP IF k NOT IN('job_sheet','eta','estimate','proposal','contract','invoice','no_access','unsigned_left') OR jsonb_typeof(v)<>'object' OR jsonb_typeof(v->'email') IS DISTINCT FROM 'boolean' OR jsonb_typeof(v->'whatsapp') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'Invalid routing preference'; END IF; IF (v->>'whatsapp')::boolean AND NOT NEW.has_whatsapp THEN RAISE EXCEPTION 'WhatsApp consent required'; END IF; END LOOP;
 IF TG_OP='UPDATE' AND NEW.site_id IS DISTINCT FROM OLD.site_id AND NEW.site_ids IS NOT DISTINCT FROM OLD.site_ids AND NEW.all_sites IS NOT DISTINCT FROM OLD.all_sites THEN NEW.all_sites:=(NEW.site_id IS NULL);NEW.site_ids:=CASE WHEN NEW.site_id IS NULL THEN '{}'::uuid[] ELSE ARRAY[NEW.site_id] END; END IF;
 IF TG_OP='UPDATE' AND NEW.receives_job_sheets IS DISTINCT FROM OLD.receives_job_sheets AND NEW.delivery_preferences IS NOT DISTINCT FROM OLD.delivery_preferences THEN NEW.delivery_preferences:=jsonb_set(NEW.delivery_preferences,'{job_sheet}',jsonb_build_object('email',NEW.receives_job_sheets,'whatsapp',coalesce((NEW.delivery_preferences->'job_sheet'->>'whatsapp')::boolean,false))); END IF;
 END IF; RETURN NEW;
END $$;
CREATE TRIGGER client_contacts_routing_guard BEFORE INSERT OR UPDATE ON public.client_contacts FOR EACH ROW EXECUTE FUNCTION public.guard_contact_routing();
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.save_client_contact(uuid,uuid,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'(_details->>''email'') !~','coalesce(_details->>''email'','''') !~'); EXECUTE definition; END $$;